using System;
using System.IO;
using System.Linq;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine.SceneManagement;
namespace Freyja.WorldBuilder.Editor {
 public static class KitPS1 {
  public const string Art="Assets/_Project/Art/KitPS1_022", Folder="Assets/_Project/WorldBuilder/Demo022";
  public static readonly string[] Surfaces={"Grass","Dirt","PathSand","BeachSand","Stone","Brick","Bark","Leaves","Rock"};
  public static readonly string[] Objects={"Rock_1","Rock_2","Rock_3","Nature_Pine","Nature_Common"};
  public static Material Material(string name)=>AssetDatabase.LoadAssetAtPath<Material>(Folder+"/"+name+".mat");
  public static WorldDefinition World=>AssetDatabase.LoadAssetAtPath<WorldDefinition>(Folder+"/Praia.asset");
  public static void Prepare(){Directory.CreateDirectory(Folder);AssetDatabase.Refresh();foreach(var name in Surfaces){string texPath=Art+"/"+name+".png";var ti=(TextureImporter)AssetImporter.GetAtPath(texPath);ti.filterMode=FilterMode.Point;ti.wrapMode=TextureWrapMode.Repeat;ti.textureCompression=TextureImporterCompression.Uncompressed;ti.mipmapEnabled=false;ti.maxTextureSize=64;ti.SaveAndReimport();var mat=Material(name);if(!mat){mat=new Material(Shader.Find("Standard"));AssetDatabase.CreateAsset(mat,Folder+"/"+name+".mat");}mat.mainTexture=AssetDatabase.LoadAssetAtPath<Texture2D>(texPath);mat.color=Color.white;mat.SetFloat("_Glossiness",0);EditorUtility.SetDirty(mat);}
   foreach(var id in Objects){string sourcePath=id.StartsWith("Nature")?"Assets/ThirdParty/Nature022/"+id+".fbx":Art+"/"+id+".fbx";var model=AssetDatabase.LoadAssetAtPath<GameObject>(sourcePath);var wrapper=new GameObject(id);try{var visual=(GameObject)PrefabUtility.InstantiatePrefab(model,wrapper.transform);foreach(var r in visual.GetComponentsInChildren<Renderer>()){r.sharedMaterials=r.sharedMaterials.Select(m=>Material(m&&m.name.Contains("Bark")?"Bark":id.StartsWith("Nature")?"Leaves":"Rock")).ToArray();}var bounds=ExternalModelNormalizer.BoundsOf(wrapper);visual.transform.localPosition-=new Vector3(bounds.center.x,bounds.min.y,bounds.center.z);if(id.StartsWith("Nature")){var c=wrapper.AddComponent<CapsuleCollider>();c.radius=.28f;c.height=2.8f;c.center=new Vector3(0,1.4f,0);}else{var c=wrapper.AddComponent<BoxCollider>();c.center=new Vector3(0,bounds.size.y/2,0);c.size=bounds.size;}wrapper.layer=8;PrefabUtility.SaveAsPrefabAsset(wrapper,Folder+"/"+id+".prefab");}finally{UnityEngine.Object.DestroyImmediate(wrapper);}}
   AssetDatabase.SaveAssets();
  }
  public static WorldDefinition Create(){if(World)return World;Prepare();var w=ScriptableObject.CreateInstance<WorldDefinition>();w.worldId="freyja-ps1-022";w.size=new Vector2(64,64);w.terrainHeight=12;w.originY=-2;w.resolution=257;w.amplitude=6;w.roadMaterial=Material("Dirt");w.foundationMaterial=Material("Stone");w.terrainLayers=new TerrainLayer[4];for(int i=0;i<4;i++){var layer=new TerrainLayer{diffuseTexture=Material(Surfaces[i]).mainTexture as Texture2D,tileSize=new Vector2(2,2),smoothness=0};AssetDatabase.CreateAsset(layer,Folder+"/"+Surfaces[i]+".terrainlayer");w.terrainLayers[i]=layer;}w.grass=w.terrainLayers[0];
   var td=new TerrainData{heightmapResolution=257,size=new Vector3(64,12,64)};var h=new float[257,257];for(int z=0;z<257;z++)for(int x=0;x<257;x++){float px=x/256f*64-32,pz=z/256f*64-32;float coast=Mathf.SmoothStep(0,1,Mathf.InverseLerp(-25,-17,pz));float y=Mathf.Lerp(-1.2f,.6f,coast)+Mathf.SmoothStep(0,1,Mathf.InverseLerp(-12,23,pz))*5.4f;y+=Mathf.Exp(-((px-19)*(px-19)+(pz-14)*(pz-14))/160)*2;float edge=Mathf.SmoothStep(0,1,Mathf.InverseLerp(26,32,Mathf.Abs(px)));y=Mathf.Lerp(y,-1.1f,edge);h[z,x]=(y+2)/12;}td.SetHeights(0,0,h);AssetDatabase.CreateAsset(td,Folder+"/CoastalBase.asset");w.baseTerrain=td;
   w.roads.Add(new RoadDefinition{id="praia-casa",start=new Vector2(0,-14),end=new Vector2(0,23),width=3.5f,startY=.65f,endY=5.4f});w.lots.Add(new LotDefinition{id="casa-praia",center=new Vector2(-15,12),yaw=90,manualHeight=true,foundationY=4.8f,prefab=AssetDatabase.LoadAssetAtPath<GameObject>(WorldGenerator.Folder+"/Casa1.prefab")});AssetDatabase.CreateAsset(w,Folder+"/Praia.asset");AssetDatabase.SaveAssets();return w;
  }
  public static void ResetPaint(WorldDefinition w){var t=WorldGenerator.FindRoot(w).GetComponentInChildren<Terrain>();var td=t.terrainData;Undo.RegisterCompleteObjectUndo(td,"Reiniciar pintura");foreach(var tex in td.alphamapTextures)Undo.RegisterCompleteObjectUndo(tex,"Reiniciar pintura");td.terrainLayers=w.terrainLayers;int n=td.alphamapResolution;var a=new float[n,n,4];for(int z=0;z<n;z++)for(int x=0;x<n;x++){float pz=z/(float)(n-1)*64-32;float sand=1-Mathf.SmoothStep(0,1,Mathf.InverseLerp(-14,-7,pz));a[z,x,3]=sand;a[z,x,0]=1-sand;}td.SetAlphamaps(0,0,a);td.SetBaseMapDirty();EditorUtility.SetDirty(td);foreach(var tex in td.alphamapTextures)EditorUtility.SetDirty(tex);AssetDatabase.SaveAssets();}
  public static GameObject Place(string id,Vector3 position){var root=WorldGenerator.FindRoot(World);if(!root)throw new InvalidOperationException("Abra o trecho primeiro.");var prefab=AssetDatabase.LoadAssetAtPath<GameObject>(Folder+"/"+id+".prefab");var go=(GameObject)PrefabUtility.InstantiatePrefab(prefab,root.transform);Undo.RegisterCreatedObjectUndo(go,"Colocar "+id);go.transform.position=position;Selection.activeGameObject=go;EditorSceneManager.MarkSceneDirty(SceneManager.GetActiveScene());return go;}
  public static string Activate(){if(EditorApplication.isPlaying)throw new InvalidOperationException("Saia de Play Mode.");var w=Create();bool fresh=!WorldGenerator.FindRoot(w);var previous=AssetDatabase.LoadAssetAtPath<WorldDefinition>(WorldDemo.Data);var old=previous?WorldGenerator.FindRoot(previous):null;if(old)old.SetActive(false);var root=WorldDemo.Activate(w);if(fresh){ResetPaint(w);var terrain=root.GetComponentInChildren<Terrain>();foreach(var item in new[]{("Nature_Pine",-23f,13f),("Nature_Common",-21f,4f),("Nature_Pine",18f,17f),("Nature_Common",10f,2f),("Rock_1",-13f,-19f),("Rock_2",-19f,-18f),("Rock_3",17f,-14f),("Rock_2",22f,-13f),("Rock_1",-25f,0f)}){var pos=new Vector3(item.Item2,0,item.Item3);pos.y=terrain.transform.position.y+terrain.terrainData.GetInterpolatedHeight(pos.x/64+.5f,pos.z/64+.5f);Place(item.Item1,pos);}var sea=GameObject.CreatePrimitive(PrimitiveType.Plane);sea.name="Mar — referência visual";sea.transform.SetParent(root.transform);sea.transform.position=new Vector3(0,-.1f,0);sea.transform.localScale=new Vector3(20,1,20);UnityEngine.Object.DestroyImmediate(sea.GetComponent<Collider>());var mat=new Material(Shader.Find("Unlit/Color")){color=new Color(.15f,.39f,.43f)};AssetDatabase.CreateAsset(mat,Folder+"/Sea.mat");sea.GetComponent<Renderer>().sharedMaterial=mat;}
   var session=GameObject.Find("Cais Session").GetComponents<MonoBehaviour>().First(c=>c.GetType().Name=="CaisSessionController");var settings=new SerializedObject(session);settings.FindProperty("controlsTitle").stringValue="FREYJA — PRAIA";settings.ApplyModifiedPropertiesWithoutUndo();
   var spawn=root.transform.Find("Spawn021");spawn.position=new Vector3(0,.82f,-18);var player=GameObject.Find("PlayerPrototype");var cc=player.GetComponent<CharacterController>();bool enabled=cc.enabled;cc.enabled=false;player.transform.position=spawn.position;cc.enabled=enabled;GameObject.Find("Cais Gameplay Camera").transform.SetPositionAndRotation(spawn.position+new Vector3(0,4,-10),Quaternion.Euler(18,0,0));AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(SceneManager.GetActiveScene());if(SceneView.lastActiveSceneView)SceneView.lastActiveSceneView.LookAt(new Vector3(0,2,0),Quaternion.Euler(40,-30,0),45);return root.name;
  }
 }
}
